<?php
$id=(int)($_GET['id']??0);$unit=['id'=>0,'unit_code'=>'','unit_name'=>'','category'=>'','brand'=>'','model'=>'','serial_number'=>'','location'=>'','meter_type'=>'HM','current_meter'=>0,'operational_status'=>'Ready for Use'];
if($id){$stmt=$pdo->prepare('SELECT * FROM units WHERE id=?');$stmt->execute([$id]);$unit=$stmt->fetch()?:$unit;}
?>
<div class="card panel form-card"><h3><?=$id?'Edit':'Tambah'?> Unit</h3><form method="post" action="actions/save_unit.php"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$unit['id']?>"><div class="form-grid">
<label>Kode Unit<input name="unit_code" value="<?=e($unit['unit_code'])?>" required></label><label>Nama Unit<input name="unit_name" value="<?=e($unit['unit_name'])?>" required></label><label>Kategori<input name="category" value="<?=e($unit['category'])?>" required></label><label>Merek<input name="brand" value="<?=e($unit['brand'])?>"></label><label>Model<input name="model" value="<?=e($unit['model'])?>"></label><label>Serial Number<input name="serial_number" value="<?=e($unit['serial_number'])?>"></label><label>Lokasi<input name="location" value="<?=e($unit['location'])?>"></label><label>Jenis Meter<select name="meter_type"><option <?= $unit['meter_type']==='HM'?'selected':'' ?>>HM</option><option <?= $unit['meter_type']==='KM'?'selected':'' ?>>KM</option></select></label><label>Meter Aktual<input type="number" step="0.01" name="current_meter" value="<?=e((string)$unit['current_meter'])?>"></label><label>Status<select name="operational_status"><?php foreach(['Ready for Use','Breakdown','Downtime','Maintenance'] as $s): ?><option <?=$unit['operational_status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></label></div><div class="form-actions"><a class="btn" href="<?=page_url('units')?>">Batal</a><button class="btn primary">Simpan</button></div></form></div>
